INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 28, 'theory', 'Quiz: performance');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 0, 'What are the Core Web Vitals judged by?', '["By the average", "By the best measurement", "By the 75th percentile of real users", "By a single lab run"]', 2, 'The average hides slow users, and a single run is noisy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 1, 'Which task counts as a long task?', '["Longer than 50 ms", "Longer than 5 ms", "Longer than 500 ms", "Any asynchronous one"]', 0, 'While a task longer than 50 ms runs, the page doesn''t respond to input.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 2, 'What causes layout thrashing?', '["Using transform", "Alternating style writes and dimension reads in a loop", "Lazy loading", "The defer attribute"]', 1, 'Reading dimensions after a write forces the browser to recalculate layout at once; read everything first, then write.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 3, 'Why virtualize a long list?', '["To compress the data", "To speed up the network", "To remove sorting", "To keep only the visible rows in the document"]', 3, 'The total height is imitated with an empty block, and the range of indexes is computed from the scroll position.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 4, 'What keeps a page out of the bfcache?', '["An unload handler and Cache-Control: no-store", "The immutable header", "The loading=lazy attribute", "Brotli"]', 0, 'The back-forward cache doesn''t keep pages that can''t be safely "frozen".');
